package com.hivepulse.app.ui.calendar

// Generated by scripts/fetch_year_photos.py -- do not edit by hand.
//
// A photograph for the jobs that have one. Most are CC BY or CC BY-SA, so the author and
// the licence travel with the picture and are shown wherever it is: that is the whole of
// what those licences ask for, and it is also the honest thing to show.
//
// Jobs without a photograph are not an oversight -- see WITHOUT in the script. They keep
// their drawn icon, and every layout copes with a missing picture.

/**
 * One photograph, with what its licence obliges us to show.
 *
 * @param file the 640x427 crop, a path inside the app's assets.
 * @param thumb a 128px square tile for the list, a fortieth of the weight.
 * @param source the file's page on Wikimedia Commons.
 */
data class YearPhoto(
    val file: String,
    val thumb: String,
    val author: String,
    val licence: String,
    val licenceUrl: String,
    val source: String,
)

