    /**
     * The photograph for one calendar entry, or null when it has none.
     *
     * An entry that names a forage shows that plant, whatever the job is. Everything else
     * shows the job itself.
     */
    fun of(entryKey: String, honey: String? = null): YearPhoto? =
        honey?.let { BY_FORAGE[it] } ?: BY_KEY[entryKey]
